(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zze-sj-prepa-gyneco-j6-sf3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zze-sj-prepa-gyneco-j6-sf3\",\n \"titre\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 40,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J6_Gyneco_SF3_corrige_explique.pdf\",\n   \"sha256\": \"f97f95c20e6638b9550be57c5067481265977d038a2b43f4721425d68371b3e8\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n     \"slug\": \"prepa-gyneco-j6-sf3\",\n     \"pages\": \"\",\n     \"count\": 40,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Gynéco-obstétrique\",\n     \"source\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le petit bassin osseux maternel comprend 3 parties qui sont : le détroit supérieur, le détroit moyen et le détroit inférieur\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Sur le plan obstétrical, le petit bassin (excavation pelvienne) constitue la filière osseuse que traverse le fœtus lors de l'accouchement ; il se subdivise anatomiquement en trois étages successifs : le détroit supérieur (entrée), l'excavation pelvienne avec le détroit moyen (plan des épines sciatiques) et le détroit inférieur (sortie).\\n\\nSource : Cours de Gynéco-Obstétrique — Anatomie du bassin obstétrical.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'ovogonie est un gamète femelle qui a 2 x 22 chromosomes\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'ovogonie est une cellule germinale souche diploïde possédant 46 chromosomes (soit 2 × 23 chromosomes : 22 paires d'autosomes et une paire de gonosomes XX), tandis que le gamète femelle mature (ovule) est haploïde avec 23 chromosomes.\\n\\nSource : Cours de Gynéco-Obstétrique — Gamétogenèse et ovogenèse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le repère de la présentation de la face est le menton.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans la présentation céphalique défléchie de la face, le repère anatomique qui permet de définir les variétés de position (mento-iliaque gauche ou droite, antérieure ou postérieure) est le menton fœtal.\\n\\nSource : Cours de Gynéco-Obstétrique — Les présentations céphaliques (présentation de la face).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Après la naissance, les 1ères règles permettent de dater la puberté\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'apparition des premières menstruations (ménarches) constitue l'événement clinique marquant qui permet de dater et d'attester la puberté chez la jeune fille dans l'interrogatoire gynécologique.\\n\\nSource : Cours de Gynéco-Obstétrique — Physiologie du cycle menstruel et puberté.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de la grossesse normale, le poids de la gestante peut augmenter\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La grossesse normale s'accompagne d'une prise de poids physiologique régulière (en moyenne 9 à 12 kg sur l'ensemble de la grossesse, soit environ 1 kg par mois aux deux premiers trimestres puis 1,5 à 2 kg par mois au troisième trimestre) liée au fœtus, aux annexes et aux réserves maternelles.\\n\\nSource : Cours de Gynéco-Obstétrique — Modifications physiologiques de la grossesse et CPN.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les modifications physiologiques de l'organisme maternel au cours de la grossesse débutent avant la fécondation\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les adaptations physiologiques maternelles de la grossesse sont induites par les sécrétions hormonales du corps jaune gravidique puis du placenta (hCG, progestérone, œstrogènes) ; elles débutent donc après la fécondation et l'implantation de l'œuf.\\n\\nSource : Cours de Gynéco-Obstétrique — Modifications physiologiques de l'organisme maternel pendant la grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les 1ères règles s'appellent les ménarches\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"On désigne par le terme « ménarches » la survenue des toutes premières règles chez l'adolescente à la puberté.\\n\\nSource : Cours SSR-PF / Gynéco-Obstétrique — Interrogatoire gynécologique (p. 26).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La prescription de fer est interdite au 1er trimestre de grossesse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La supplémentation martialo-folique (fer + acide folique) n'est pas contre-indiquée au premier trimestre de grossesse ; elle est au contraire recommandée dès la première consultation prénatale (CPN 1) pour prévenir l'anémie maternelle et les anomalies de fermeture du tube neural.\\n\\nSource : Cours de Gynéco-Obstétrique — Surveillance prénatale et prévention de l'anémie gravidique.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La sérologie de la toxoplasmose positive à Ig M témoigne d'une atteinte toxoplasmique\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La présence d'immunoglobulines M (IgM) spécifiques anti-Toxoplasma gondii oriente vers une infection toxoplasmique récente ou évolutive (nécessitant un contrôle de la cinétique des IgG et un test d'avidité pour dater précisément la contamination).\\n\\nSource : Cours de Gynéco-Obstétrique — Toxoplasmose et grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au 1er trimestre de grossesse, la présence des Ig G durant la sérologie de la rubéole signe une primo-infection de la rubéole qui est très grave\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La présence isolée d'IgG anti-rubéoleuses (en l'absence d'IgM) témoigne au contraire d'une immunité ancienne protectrice (post-vaccinale ou post-infectieuse) qui protège le fœtus ; c'est la présence d'IgM (et la séroconversion) qui traduit une primo-infection récente grave.\\n\\nSource : Cours de Gynéco-Obstétrique — Rubéole et grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de la grossesse, l'association d'une TA égale à 15/10 cmHg, d'une protéinurie à 3 croix et d'une crise convulsive signe une pré-éclampsie très sévère\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dès lors qu'une crise convulsive généralisée survient chez une patiente atteinte de pré-éclampsie (HTA gravidique + protéinurie), le tableau clinique n'est plus une simple pré-éclampsie sévère mais devient par définition une crise d'éclampsie (complication paroxystique majeure).\\n\\nSource : Cours de Gynéco-Obstétrique / SONU — Syndromes vasculo-rénaux : pré-éclampsie et éclampsie.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"On parle d'hydramnios quand la quantité de liquide amniotique dépasse 2 litres dans les derniers mois de grossesse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'hydramnios (ou polyhydramnios) se définit cliniquement et anatomiquement par un excès pathologique de liquide amniotique supérieur à 2 000 ml (2 litres) au troisième trimestre de la grossesse (la quantité physiologique à terme étant comprise entre 500 et 1 000 ml).\\n\\nSource : Cours de Gynéco-Obstétrique — Pathologies des annexes fœtales (hydramnios).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La survenue d'agitation, de confusion, ou de délire durant un paludisme à plasmodium falciparum au cours de la grossesse traduit automatiquement un paludisme grave\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Chez la femme enceinte infectée par Plasmodium falciparum, tout trouble neuropsychique (agitation, confusion mentale, obnubilation, délire, convulsions ou coma) constitue un signe clinique de neuropaludisme et classe d'emblée le tableau en paludisme grave nécessitant une prise en charge parentérale en urgence.\\n\\nSource : Cours de Gynéco-Obstétrique — Paludisme et grossesse (critères de gravité).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours de la grossesse, un taux d'hémoglobine égal à 10,2 g/100ml avec un CCMH = 26 picogrammes et un VGM = 70 µ3 évoquent une anémie hypochrome microcytaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Anémie de la grossesse : Hb < 11 g/100 ml (ici 10,2) ; hypochrome : CCMH < 27 pg (ici 26) ; microcytaire : VGM < 80 µ3 (ici 70). Le tableau correspond à une anémie hypochrome microcytaire (carence martiale).\\n\\nSource : GYNECO L2 IDE VERSION 2025, Anémie et grossesse, III/3-2 Examens complémentaires\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Il est recommandé de donner une supplémentation de fer à une gestante ayant une hémoglobinose AS à partir du 2ème trimestre de grossesse pour éviter une anémie ferriprive\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Contrairement aux syndromes drépanocytaires majeurs (SS, SC, Sβ-thalassémie) où le fer est contre-indiqué en raison du risque de surcharge martiale, la gestante porteuse d'un trait drépanocytaire hétérozygote asymptomatique (AS) doit recevoir une supplémentation en fer et acide folique comme toute femme enceinte pour prévenir l'anémie ferriprive.\\n\\nSource : Cours de Gynéco-Obstétrique — Drépanocytose et grossesse.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les signes suivants, relever celui ou ceux qui caractérise(nt) le placenta prævia marginal hémorragique dans sa forme typique :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Ménorragies indolores faites de sang rouge au 3ème trimestre de grossesse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Métrorragies faites de sang rouge au 3ème trimestre de grossesse avec des contractions utérines\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Métrorragies indolores faites de sang noir au 3ème trimestre de grossesse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Petit côté des membranes mesurant moins de 10 cm\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Petit côté des membranes mesurant moins de 9 cm\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Métrorragies faites de sang rouge vif au 3ème trimestre de grossesse avec des\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. D : Petit côté des membranes mesurant moins de 10 cm\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Anatomiquement, l'insertion basse du placenta (placenta prævia latéral ou marginal) est affirmée après la délivrance lorsque la mesure du petit côté des membranes (distance entre l'orifice de rupture des membranes et le bord le plus proche du placenta) est inférieure à 10 cm. Sur le plan clinique, les métrorragies du placenta prævia sont spontanées, indolores, faites de sang rouge vif et sans contractions utérines (les options a, b, c et f sont donc inexactes).\\n\\nSource : Cours de Gynéco-Obstétrique — Hémorragies du 3e trimestre : le placenta prævia.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Relever la ou les manœuvre(s) à exécuter pour extraire la tête dernière retenue dans l'excavation pelvienne dans l'accouchement du siège.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Attitude de Vermelin\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Petite extraction du siège\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Grande extraction du siège\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Manœuvre de Bracht\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Manœuvre de Lovset\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Manœuvre de Mauriceau\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"F. F : Manœuvre de Mauriceau\",\n       \"answerLetters\": [\n        \"F\"\n       ],\n       \"explanation\": \"La manœuvre de Mauriceau est la manœuvre obstétricale spécifique permettant de fléchir, orienter et extraire la tête dernière lorsque celle-ci est retenue dans l'excavation pelvienne au cours d'un accouchement du siège. La manœuvre de Lovset sert au dégagement des épaules/bras relevés et l'attitude de Vermelin correspond à l'abstention interventionniste lors de l'expulsion spontanée.\\n\\nSource : Cours de Gynéco-Obstétrique / SONU — Accouchement en présentation du siège.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le début du cycle menstruel commence toujours :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Au 1er jour de survenue des règles\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Au début des règles\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : A la fin des règles\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : A l'ovulation\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Au dernier jour précédant les règles\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Au 1er jour des ménarches\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A : Au 1er jour de survenue des règles\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Par convention physiologique et clinique, le premier jour du cycle menstruel (J1) correspond au premier jour de l'apparition des menstruations (règles) et se termine la veille des règles suivantes.\\n\\nSource : Cours de Gynéco-Obstétrique — Le cycle menstruel (p. 28-30).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la présentation de la face, on sent au TV toujours :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : La grande fontanelle du fœtus.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : La petite fontanelle du fœtus.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Le front du fœtus.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Le menton du fœtus.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Les yeux du fœtus.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : La bouche du fœtus.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D : Le menton du fœtus.\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Au toucher vaginal, le diagnostic positif de la présentation de la face repose sur la perception de l'ensemble de la face défléchie et impérativement de son repère caractéristique, le menton (ainsi que les arcades orbitaires, le nez et la bouche), sans jamais percevoir ni la grande ni la petite fontanelle.\\n\\nSource : Cours de Gynéco-Obstétrique — Diagnostic de la présentation de la face.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Après la réfection de l'épisiotomie, le soin ci-dessous ne doit pas ou les soins ci-dessous ne doivent pas être prodigués\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Faire bain de siège avec de l'eau froide\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Appliquer en permanence un linge mouillé sur la suture\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Assécher la suture\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Faire un pansement occlusif sur la suture\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Faire un pansement non occlusif sur la suture\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Faire bain de siège avec de l'eau tiède ou chaude sur la suture\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A : Faire bain de siège avec de l'eau froide ; B. B : Appliquer en permanence un linge mouillé sur la suture ; D. D : Faire un pansement occlusif sur la suture ; F. F : Faire bain de siège avec de l'eau tiède ou chaude sur la suture\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Après la suture d'une épisiotomie, la plaie périnéale doit rester propre et sèche pour favoriser la cicatrisation et éviter la macération et l'infection : les bains de siège (à l'eau froide ou chaude), l'application permanente de linge humide et les pansements occlusifs sont proscrits. On réalise une toilette vulvaire antiseptique suivie d'un séchage soigneux et d'une garniture propre non occlusive.\\n\\nSource : Cours de Gynéco-Obstétrique / Soins obstétricaux — Soins post-épisiotomie (p. 67).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, relever celle qui est fausse ou celles qui sont fausses\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Le cordon ombilical contient 3 vaisseaux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Le fibrome utérin involue à la ménopause.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Le fibrome utérin est cause de stérilité\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Le liquide amniotique est produit principalement par le fœtus\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : A terme, le poids du placenta est égal au 1/6 du poids du fœtus.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Le cordon ombilical s'insère sur la face maternelle du placenta.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"F. F : Le cordon ombilical s'insère sur la face maternelle du placenta.\",\n       \"answerLetters\": [\n        \"F\"\n       ],\n       \"explanation\": \"Le cordon ombilical s'insère sur la face fœtale (lisse, brillante, tapissée par l'amnios) du placenta, tandis que la face maternelle est charnue, rougeâtre et divisée en cotylédons appliqués contre la caduque utérine. Toutes les autres propositions (3 vaisseaux, involution à la ménopause, cause d'infertilité, origine fœtale du liquide amniotique et poids placentaire égal à 1/6 du poids fœtal) sont exactes.\\n\\nSource : Cours de Gynéco-Obstétrique — Étude des annexes fœtales (placenta et cordon ombilical) et fibromes utérins.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les facteurs suivants, relever celui qui est ou ceux qui sont classiquement des facteurs de risque de survenue du cancer du col utérin\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Cervicite virale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Réalisation de façon régulière des examens de dépistage\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Partenaires sexuels multiples\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Nulliparité\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Premier accouchement après 30 ans\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Antécédents de cancer du col chez la mère\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A : Cervicite virale ; C. C : Partenaires sexuels multiples\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Le cancer du col de l'utérus est lié à une infection persistante par les virus HPV oncogènes (cervicite virale à papillomavirus humain), favorisée par la précocité des rapports sexuels et la multiplicité des partenaires sexuels. La multiparité précoce (et non la nulliparité ni un 1er accouchement tardif) est un cofacteur, tandis que le dépistage régulier (IVA/IVL, FCU) est un facteur protecteur.\\n\\nSource : Cours de Gynéco-Obstétrique — Cancer du col de l'utérus (étiologie et facteurs de risque).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les signes suivants évoquent une grossesse môlaire :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Métrorragies spontanées faites de sang rouge au cours du 1er trimestre de grossesse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Métrorragies spontanées de sang noir au cours du 1er trimestre de grossesse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Métrorragies provoquées de sang rouge au cours du 1er trimestre de grossesse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Sialorrhée et vomissements au cours du 1er trimestre de grossesse associés à un placenta ressemblant aux frais de grenouille\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Aménorrhée\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Ménorragie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. A : Métrorragies spontanées faites de sang rouge au cours du 1er trimestre de grossesse ; D. D : Sialorrhée et vomissements au cours du 1er trimestre de grossesse associés à un placenta ressemblant aux frais de grenouille ; E. E : Aménorrhée\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"La môle hydatiforme se manifeste au premier trimestre sur un fond d'aménorrhée gravidique par des métrorragies spontanées récidivantes faites de sang rouge, des signes sympathiques de grossesse exacerbés (vomissements incoercibles, sialorrhée liés à l'hyper-sécrétion de β-hCG) et l'expulsion caractéristique de vésicules translucides en grappe de raisin ou « frai de grenouille ».\\n\\nSource : Cours de Gynéco-Obstétrique — Môle hydatiforme (p. 131).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__23\",\n       \"num\": \"24\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"1er CAS CLINIQUE. Ce jour à 5 heures, Mme B.B.B. 30 ans, G6, P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail d'accouchement a commencé à 4 h. La hauteur utérine = 36 cm. Température = 36°,9 C. Le col est dilaté à 5 cm. Le taux d'hémoglobine = 10 g/100ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 heures 20 minutes d'une fille pesant 4000 grammes, à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 heures 30 minutes sans GATPA par TCC. Mme B.B.B. risque de saigner abondamment et mourir.\",\n       \"text\": \"Parmi les propositions suivantes, relever le geste ou les gestes à exécuter vis-à-vis de ce nouveau-né :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Massage cardiaque externe\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Demander de l'aide et expliquer doucement à la mère les gestes à faire.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Couper aussitôt le cordon ombilical avant 1 mn de vie.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Bien placer le nouveau-né en décubitus dorsal, le cou en extension modérée.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Libérer les voies aériennes.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Administration des médicaments pour faire respirer ce nouveau-né\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B : Demander de l'aide et expliquer doucement à la mère les gestes à faire. ; D. D : Bien placer le nouveau-né en décubitus dorsal, le cou en extension modérée. ; E. E : Libérer les voies aériennes.\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Devant un nouveau-né en asphyxie néonatale qui ne crie pas et ne respire pas à la naissance, les premiers gestes de réanimation néonatale de base (SONU) consistent à appeler à l'aide et rassurer/informer la mère, installer le nouveau-né séché et réchauffé en décubitus dorsal avec la tête en position neutre (cou en légère extension) et désobstruer/libérer les voies aériennes supérieures avant d'initier la ventilation au ballon et au masque.\\n\\nSource : Cours SONU / Pédiatrie — Réanimation du nouveau-né en salle de naissance.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__24\",\n       \"num\": \"25\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"1er CAS CLINIQUE. Ce jour à 5 heures, Mme B.B.B. 30 ans, G6, P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail d'accouchement a commencé à 4 h. La hauteur utérine = 36 cm. Température = 36°,9 C. Le col est dilaté à 5 cm. Le taux d'hémoglobine = 10 g/100ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 heures 20 minutes d'une fille pesant 4000 grammes, à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 heures 30 minutes sans GATPA par TCC. Mme B.B.B. risque de saigner abondamment et mourir.\",\n       \"text\": \"Grâce à ces gestes correctement exécutés, ce nouveau-né a une ventilation spontanée efficace, durable et tout va très bien. Néanmoins, vous décidez de surveiller l'accouchée et son nouveau-né. Entre 5 h30mn et 7 h30 mn, chez la mère vous allez surveiller le ou les paramètres suivants\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Les lochies pour rechercher une endométrite du post-partum.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : La TA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Le pouls.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : L'écoulement vulvaire pour rechercher un saignement anormal.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Le globe de sécurité.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Les conjonctives pour rechercher un ictère.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. B : La TA. ; C. C : Le pouls. ; D. D : L'écoulement vulvaire pour rechercher un saignement anormal. ; E. E : Le globe de sécurité.\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Dans les 2 heures qui suivent l'accouchement, on surveille la TA, le pouls, l'écoulement vulvaire (saignement) et le globe de sécurité utérin, pour dépister une hémorragie. L'endométrite (lochies) et l'ictère ne se recherchent pas à ce moment.\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, Soins à l'accouchée, 1-2 Surveillance ; COURS GYNECO OBSTETRIQUE (1re année commune), suites de couches, III.1.1\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__25\",\n       \"num\": \"26\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"1er CAS CLINIQUE. Ce jour à 5 heures, Mme B.B.B. 30 ans, G6, P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail d'accouchement a commencé à 4 h. La hauteur utérine = 36 cm. Température = 36°,9 C. Le col est dilaté à 5 cm. Le taux d'hémoglobine = 10 g/100ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 heures 20 minutes d'une fille pesant 4000 grammes, à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 heures 30 minutes sans GATPA par TCC. Mme B.B.B. risque de saigner abondamment et mourir.\",\n       \"text\": \"En dehors de tout élément anormal, la fréquence normale de cette surveillance entre 6 h30mn et 7h30 mn est : (Relever la fréquence correcte)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Toutes les 10 mn\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Toutes les 15 mn\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Toutes les 30 mn\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Toutes les 40 mn\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Toutes les 60 mn\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Toutes les 20 mn\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C : Toutes les 30 mn\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient une surveillance toutes les 30 minutes pendant les 2 premières heures du post-partum, comme le cours de 1re année. Remarque : Le cours de Soins obstétricaux et le chapitre « soins à l'accouchée » du cours de 1re année donnent une autre périodicité : toutes les 15 min pendant les 2 premières heures, puis toutes les 30 min pendant la 3e heure.\\n\\nSource : COURS GYNECO OBSTETRIQUE (1re année commune), Suites de couches normales, III.1.1 (« toutes les 30 mn pendant 2 heures »)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__26\",\n       \"num\": \"27\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"1er CAS CLINIQUE. Ce jour à 5 heures, Mme B.B.B. 30 ans, G6, P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail d'accouchement a commencé à 4 h. La hauteur utérine = 36 cm. Température = 36°,9 C. Le col est dilaté à 5 cm. Le taux d'hémoglobine = 10 g/100ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 heures 20 minutes d'une fille pesant 4000 grammes, à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 heures 30 minutes sans GATPA par TCC. Mme B.B.B. risque de saigner abondamment et mourir.\",\n       \"text\": \"A 6h, Mme BBB a saigné 100ml par voie vaginale ; elle transpire abondamment, sa TA = 6/4 cmHg, son pouls = 120/mn, ses conjonctives sont blanches et pas d'ictère, le périnée est intact. Selon vous, de quoi souffre Mme BBB ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Hémorragie du Post Partum\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Hémorragie du Post Partum immédiat\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Hémorragie du Post Partum tardif\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Hémorragie du Post Partum immédiat par atonie utérine\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Hémorragie du Post Partum immédiat par trouble de la coagulation\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Hémorragie du Post Partum immédiat par déchirure périnéale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. D : Hémorragie du Post Partum immédiat par atonie utérine\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Trente minutes après l'accouchement, la patiente présente un état de choc hémorragique sévère (TA effondrée à 6/4 cmHg, tachycardie à 120/mn, sueurs, pâleur conjonctivale) avec un périnée intact et sur un terrain de grande multiparité, macrosomie (4 000 g) et absence de GATPA, ce qui signe une hémorragie du postpartum immédiat par atonie utérine (principale étiologie de l'HPPI).\\n\\nSource : Cours de Gynéco-Obstétrique / SONU — Hémorragie du post-partum immédiat (HPPI).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__27\",\n       \"num\": \"28\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"1er CAS CLINIQUE. Ce jour à 5 heures, Mme B.B.B. 30 ans, G6, P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail d'accouchement a commencé à 4 h. La hauteur utérine = 36 cm. Température = 36°,9 C. Le col est dilaté à 5 cm. Le taux d'hémoglobine = 10 g/100ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 heures 20 minutes d'une fille pesant 4000 grammes, à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 heures 30 minutes sans GATPA par TCC. Mme B.B.B. risque de saigner abondamment et mourir.\",\n       \"text\": \"Parmi les propositions suivantes, relever, chez Mme BBB, le ou les facteurs de risque de survenue de cette pathologie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Mme B.B.B. admise à 5 heures et le col est dilaté à 5 cm\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Taux d'hémoglobine = = 10 g/100ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Accouchement d'un garçon pesant 4000 grammes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Hauteur utérine = 36 cm\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Début de travail à 4 h et Mme B.B.B. donne naissance à 5 heures 20 minutes\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Hauteur utérine=37 cm\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. C : Accouchement d'un garçon pesant 4000 grammes ; D. D : Hauteur utérine = 36 cm ; E. E : Début de travail à 4 h et Mme B.B.B. donne naissance à 5 heures 20 minutes\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Les facteurs favorisant la survenue de l'atonie utérine dans cette observation sont la surdistension utérine (macrosomie fœtale de 4 000 g et hauteur utérine excessive à 36 cm) ainsi que l'accouchement rapide/précipité (durée totale du travail de 1 h 20, de 4 h à 5 h 20, sur grande multiparité G6P5). L'anémie préexistante (Hb = 10 g/dl) est un facteur d'aggravation et non de déclenchement du saignement. Remarque : dans l'énoncé du cas clinique, le nouveau-né est de sexe féminin (« d'une fille pesant 4000 grammes »), alors que l'option c mentionne « d'un garçon pesant 4000 grammes ».\\n\\nSource : Cours de Gynéco-Obstétrique / SONU — Facteurs de risque de l'hémorragie de la délivrance.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__28\",\n       \"num\": \"29\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"1er CAS CLINIQUE. Ce jour à 5 heures, Mme B.B.B. 30 ans, G6, P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail d'accouchement a commencé à 4 h. La hauteur utérine = 36 cm. Température = 36°,9 C. Le col est dilaté à 5 cm. Le taux d'hémoglobine = 10 g/100ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 heures 20 minutes d'une fille pesant 4000 grammes, à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 heures 30 minutes sans GATPA par TCC. Mme B.B.B. risque de saigner abondamment et mourir.\",\n       \"text\": \"Parmi les propositions suivantes, relever, chez Mme BBB, le ou les facteurs de risque d'aggravation de cette pathologie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Mme B.B.B. admise à 5 heures et le col est dilaté à 5 cm\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Mme B.B.B., non obèse et paroi abdominale mince\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Accouchement d'un garçon pesant 4000 grammes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Hauteur utérine à 36 cm\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Début de travail à 4 h et Mme B.B.B. donne naissance à 5 heures 20 minutes\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Taux d'hémoglobine = 10 g/100ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"F. F : Taux d'hémoglobine = 10 g/100ml\",\n       \"answerLetters\": [\n        \"F\"\n       ],\n       \"explanation\": \"Une anémie maternelle préalable à l'accouchement (taux d'hémoglobine à 10 g/100 ml) diminue les réserves érythrocytaires de la patiente et entraîne une décompensation hémodynamique beaucoup plus rapide et sévère dès les premières pertes sanguines : c'est un facteur majeur d'aggravation de l'HPPI.\\n\\nSource : Cours de Gynéco-Obstétrique / SONU — Facteurs de gravité de l'hémorragie du post-partum.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__29\",\n       \"num\": \"30\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"1er CAS CLINIQUE. Ce jour à 5 heures, Mme B.B.B. 30 ans, G6, P5, non obèse, se présente à la maternité pour des contractions utérines sur grossesse à terme. Le travail d'accouchement a commencé à 4 h. La hauteur utérine = 36 cm. Température = 36°,9 C. Le col est dilaté à 5 cm. Le taux d'hémoglobine = 10 g/100ml. Grâce à vos soins appropriés, Mme B.B.B. donne naissance à 5 heures 20 minutes d'une fille pesant 4000 grammes, à la naissance, celle-ci ne crie pas et ne respire pas. La délivrance est faite à 5 heures 30 minutes sans GATPA par TCC. Mme B.B.B. risque de saigner abondamment et mourir.\",\n       \"text\": \"Le premier geste à exécuter pour arrêter ce saignement par voie vaginale chez Mme BBB est : (Relever la réponse exacte parmi les propositions suivantes).\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Révision utérine suivie de délivrance artificielle.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Perfusion intraveineuse de 5 unités de syntocinon*(ocytocine).\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Révision utérine.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Perfusion intraveineuse d'antibiotiques et de 5 unités de syntocinon*(ocytocine).\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Délivrance artificielle suivie de révision utérine.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Délivrance artificielle.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C : Révision utérine.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La délivrance ayant déjà eu lieu à 5 h 30 (utérus supposé vide), le premier geste obstétrical endoutérin indispensable devant toute hémorragie de la délivrance survenant après expulsion du placenta est la révision utérine (sous asepsie rigoureuse) afin d'évacuer d'éventuels caillots ou débris placentaires et de stimuler la rétraction utérine, suivie du massage utérin et des utérotoniques.\\n\\nSource : Cours de Gynéco-Obstétrique / SONU — Conduite à tenir devant une hémorragie de la délivrance (p. 66).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__30\",\n       \"num\": \"31\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Ici, il s'agit d'une : (Relever la réponse exacte ou les réponses exactes parmi les propositions suivantes)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Présentation du sommet\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Présentation du siège\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Présentation du siège décomplété\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Présentation de la face tournée vers le sacrum\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Présentation du siège complet\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Présentation céphalique avec procidence des 2 pieds.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B : Présentation du siège ; E. E : Présentation du siège complet\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"La perception au toucher vaginal des deux pieds fœtaux à côté des fesses dans l'aire de dilatation (membres inférieurs fléchis, fœtus assis en tailleur) définit la présentation du siège complet (sous-type de la présentation du siège).\\n\\nSource : Cours de Gynéco-Obstétrique — La présentation du siège (variétés complète et décomplétée).\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__31\",\n       \"num\": \"32\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Ici, le repère de cette présentation est : (Relever la réponse exacte parmi les propositions suivantes)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : L'occiput du fœtus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : La racine du nez fœtal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Le sacrum du fœtus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : La petite fontanelle du fœtus\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Le menton du fœtus\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Le sacrum de la parturiente\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C : Le sacrum du fœtus\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le repère de la présentation du siège est la crête sacrée / le sacrum du fœtus (d'où la variété de position S.I.D.A. : sacro-iliaque droite antérieure). L'occiput et la petite fontanelle sont les repères du sommet, la racine du nez celui du front et le menton celui de la face.\\n\\nSource : Cours de Gynéco-Obstétrique — Repères des présentations fœtales.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__32\",\n       \"num\": \"33\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Parmi les propositions de phrases suivantes, relever la phrase qui est vraie ou les phrases qui sont vraies concernant le cas de Mme C.C.C.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Dès la fin de mon examen, je commence à remplir le partographe modifié de l'O.M.S.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Dès la fin de mon examen, je ne remplis pas le partographe modifié de l'O.M.S., car l'état de la poche des eaux n'est pas précisé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Dès la fin de mon examen, je ne commence pas à remplir le partographe modifié de l'O.M.S car il ne s'agit pas d'une présentation eutocique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Dès la fin de mon examen, je ne remplis pas le partographe modifié de l'O.M.S.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Dès la fin de mon examen, je ne remplis pas le partographe modifié de l'O.M.S., car il s'agit d'une présentation en S.I.D.A.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Dès la fin de mon examen, je ne remplis pas le partographe modifié de l'O.M.S., car je suis en périphérie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C : Dès la fin de mon examen, je ne commence pas à remplir le partographe modifié de l'O.M.S car il ne s'agit pas d'une présentation eutocique ; D. D : Dès la fin de mon examen, je ne remplis pas le partographe modifié de l'O.M.S. ; F. F : Dès la fin de mon examen, je ne remplis pas le partographe modifié de l'O.M.S., car je suis en périphérie\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Dans l'organisation obstétricale enseignée à l'INFAS, l'accouchement en présentation du siège (présentation potentiellement dystocique, surtout en siège complet) doit être pris en charge dans un centre obstétrico-chirurgical (SONU-C) et non en maternité rurale périphérique ; en conséquence, la sage-femme en périphérie ne démarre pas le suivi sur le partographe modifié de l'OMS mais organise immédiatement la référence/évacuation de la parturiente.\\n\\nSource : Cours de Gynéco-Obstétrique / SONU — Utilisation du partographe modifié de l'OMS et critères de référence.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__33\",\n       \"num\": \"34\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Concernant Mme C.C.C., l'une des phrases suivantes est synonyme d'organisation de son transfert ou les phrases suivantes sont synonymes d'organisation de son transfert depuis son admission à la maternité. (Relever cette phrase parmi les propositions suivantes)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Poche des eaux intacte\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Rupture tempestive des membranes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Rupture précoce des membranes à 5 cm.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Bruits du cœur fœtal=140/mn, réguliers et liquide amniotique méconial\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Rupture prématurée des membranes\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Rupture des membranes à 10 cm de dilatation cervicale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"F. F : Rupture des membranes à 10 cm de dilatation cervicale\",\n       \"answerLetters\": [\n        \"F\"\n       ],\n       \"explanation\": \"La correction nationale de la Prépa DE (les J) retient la proposition f (« Rupture des membranes à 10 cm de dilatation cervicale »), illustrant la règle obstétricale impérative dans la présentation du siège de respecter l'intégrité de la poche des eaux jusqu'à dilatation complète (10 cm) afin de prévenir la procidence du cordon et du pied et de faciliter la dilatation cervicale.\\n\\nSource : Cours de Gynéco-Obstétrique — Conduite à tenir au cours du travail dans la présentation du siège.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__34\",\n       \"num\": \"35\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Indiquer le geste ou les gestes à exécuter chez Mme C.C.C. dès que le col utérin est dilaté à 10 cm parmi les propositions suivantes :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Pratiquer une large épisiotomie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Perfusion intraveineuse de 5 unités de syntocinon* (ocytocine) pour renforcer les contractions utérines et empêcher le relèvement des bras du fœtus durant le TV.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Perfusion intraveineuse de 5 unités de syntocinon*(ocytocine) pour dilater le col utérin\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Faire une grande extraction du siège en l'absence de souffrance fœtale aigüe\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Surtout ne pas rompre la poche des eaux\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Injection en intramusculaire de 10 unités de syntocinon*(ocytocine)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B : Perfusion intraveineuse de 5 unités de syntocinon* (ocytocine) pour renforcer les contractions utérines et empêcher le relèvement des bras du fœtus durant le TV.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"À dilatation complète (10 cm) dans l'accouchement du siège, on met en place une perfusion d'ocytocine (5 UI de Syntocinon® dans 500 ml de sérum glucosé isotonique) afin de garantir des contractions utérines énergiques et soutenues qui maintiennent la flexion de la tête et évitent le relèvement des bras pendant l'expulsion. La grande extraction est contre-indiquée en dehors d'une souffrance fœtale aiguë.\\n\\nSource : Cours de Gynéco-Obstétrique — Prise en charge de l'expulsion dans la présentation du siège.\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__35\",\n       \"num\": \"36\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"A un moment donné, vous décidez de pratiquer une large épisiotomie. Indiquer le moment idéal pour réaliser ce geste en relevant la proposition exacte parmi les phrases ci-dessous :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Quand la tête fœtale est visible durant une contraction utérine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Quand la tête fœtale est visible en dehors d'une contraction utérine\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Quand l'anus fœtal est dilaté à 2-3 cm durant une contraction utérine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Quand l'anus maternel est dilaté à 2-3 cm durant une contraction utérine\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Dès le siège prend contact avec le périnée maternel ou quand le siège fait bomber le périnée et la hanche antérieure commence à se dégager ou quand on voit l'anus fœtal durant une contraction utérine.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Quand le col utérin est dilaté à 10 cm durant une contraction utérine\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. E : Dès le siège prend contact avec le périnée maternel ou quand le siège fait bomber le périnée et la hanche antérieure commence à se dégager ou quand on voit l'anus fœtal durant une contraction utérine.\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"L'épisiotomie large se fait dès que le siège appuie sur le périnée (le fait bomber), quand la hanche antérieure commence à se dégager, c'est-à-dire quand on voit l'anus du fœtus.\\n\\nSource : Gynécologie-Obstétrique L3, Accouchement du siège ; SONU L3, III (p. 69)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__36\",\n       \"num\": \"37\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Parmi les gestes suivants, relever celui qui doit être exécuté ou ceux qui doivent être exécutés durant la réparation d'une épisiotomie :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Suturer tous les 3 plans avec du nylon n°1\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Suturer tous les 3 plans avec du nylon n°2\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Suturer tous les 3 plans avec du fil non résorbable non serti n°1\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Commencer la suture toujours de la profondeur du vagin pour venir vers la vulve.\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Ne pas suturer l'angle supérieur de l'incision vaginale\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Réaliser la suture en un seul plan\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D : Commencer la suture toujours de la profondeur du vagin pour venir vers la vulve.\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La réfection de l'épisiotomie se fait en 3 plans successifs, au fil résorbable ; le plan vaginal commence toujours par l'angle supérieur de l'incision (profondeur du vagin) pour descendre vers la vulve (berges hyménales).\\n\\nSource : SONU L3, Épisiotomie et sa réfection, 5.1.5 Réparation (p. 63-64)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__37\",\n       \"num\": \"38\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Au cours de l'expulsion de ce fœtus en présentation du siège, il vous est recommandé de terminer rapidement cette expulsion par une manœuvre, malgré l'absence de toute dystocie. Laquelle parmi les propositions suivantes ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Je pratique la manœuvre de Mauriceau dès que je vois la pointe des omoplates du fœtus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Je pratique la manœuvre de Bracht dès que je vois la pointe des omoplates du fœtus\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Je pratique systématiquement la manœuvre de Lovset\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Je pratique la manœuvre de Mauriceau dès que je vois les oreilles du fœtus\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : J'adopte l'attitude de Vermelin\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Je pratique la manœuvre de Bracht dès que je vois les oreilles du fœtus\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. B : Je pratique la manœuvre de Bracht dès que je vois la pointe des omoplates du fœtus\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"En Côte d'Ivoire, l'accoucheur réalise systématiquement la manœuvre de Bracht dès que les pointes des omoplates apparaissent à la vulve ; l'attitude de Vermelin n'est pas recommandée.\\n\\nSource : Gynécologie-Obstétrique L3, Accouchement du siège (manœuvre de Bracht)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__38\",\n       \"num\": \"39\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Pour la cotation du score d'Apgar à 1 minute du nouveau-né, vous avez coté 2 pour la fréquence cardiaque et 1 pour chacun des autres paramètres. Ainsi, le total du score d'Apgar à 1 minute est : (Relever la bonne réponse parmi les propositions suivantes)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A:7\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B:5\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C:3\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D:4\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E:9\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F:6\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"F. F:6\",\n       \"answerLetters\": [\n        \"F\"\n       ],\n       \"explanation\": \"Le score d'Apgar comporte 5 paramètres cotés de 0 à 2 (rythme cardiaque, respiration, tonus, réactivité, coloration) : 2 + 1 + 1 + 1 + 1 = 6.\\n\\nSource : COURS DE SOINS OBSTETRICAUX 2e année SF, Soins au nouveau-né, indice d'Apgar\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-gyneco-j6-sf3__39\",\n       \"num\": \"40\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"2ème CAS CLINIQUE. Vous avez reçu, ce jour, à 6 heures, dans la maternité rurale où vous exercez, Mme C.C.C. pour des contractions utérines sur grossesse à terme. Mme C.C.C. a 27 ans, 4ème geste, 3ème pare, sans antécédent particulier. Elle a 3 contractions utérines en 10 minutes, chaque contraction utérine dure 40 secondes ; le col utérin est dilaté à 5 cm, les 2 pieds sont perçus dans l'aire de dilatation cervicale, la variété de présentation est en S.I.D.A. et le bassin est normal.\",\n       \"text\": \"Après la fin de l'accouchement de Mme C.C.C., vous pensez qu'il y a une rupture utérine ; pour cela, vous décidez de lever ce doute en réalisant :(Parmi les propositions suivantes, relever ce geste approprié ou ces gestes appropriés)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A : Perfusion intraveineuse de 5 unités de syntocinon*(ocytocine)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B : Délivrance artificielle\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C : Perfusion intraveineuse d'antibiotiques et de 5 unités de syntocinon*(ocytocine)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D : Délivrance artificielle suivie de révision utérine\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"E : Révision utérine\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"F : Révision utérine suivie de délivrance artificielle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. E : Révision utérine\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"L'accouchement et la délivrance étant achevés (« Après la fin de l'accouchement »), la vérification de l'intégrité de la paroi utérine pour confirmer ou infirmer une rupture utérine repose sur la révision utérine manuelle sous asepsie stricte, les ocytociques étant au contraire formellement contre-indiqués tant qu'une rupture utérine n'est pas éliminée.\\n\\nSource : Cours de Gynéco-Obstétrique — Indications de la révision utérine et diagnostic de rupture utérine (p. 66). CORRIGÉ EXPLIQUÉ — PRÉPA DE INFAS\",\n       \"sourceDoc\": \"Préparation D.E (J) · Gynéco-obstétrique · Prépa D.E J6 (SF3)\",\n       \"sourceFile\": \"J6_Gyneco_SF3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
